def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    Converts a :class:`datetime.timedelta` instance into a JSON‑serialisable
    representation (total seconds).  ``None`` is passed through unchanged.
    Raises :class:`TypeError` if the input is not a ``timedelta``‑like object.

    :param value: The value to dehydrate.
    :type value: datetime.timedelta or None
    :return: Total seconds as a float, or ``None``.
