def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    import collections
    import functools

    if not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer")
    if maxsize < 0:
        raise ValueError("maxsize must be non-negative")

    def decorating_function(user_function):
        cache = collections.OrderedDict()
        hits = misses = 0

        @functools.wraps(user_function)
        def wrapper(*args, **kwds):
            nonlocal hits, misses
            try:
                if typed:
                    key = tuple((arg, type(arg)) for arg in args) + \
                          tuple((k, kwds[k], type(kwds[k])) for k in sorted(kwds))
                else:
                    key = args + tuple(sorted(kwds.items()))
            except TypeError:
                # Unhashable arguments
                raise TypeError("unhashable type used as cache key")

            if key in cache:
                hits += 1
                # Move to end to mark as recently used
                cache.move_to_end(key)
                return cache[key]
            misses += 1
            result = user_function(*args, **kwds)
            cache[key] = result
            if maxsize > 0 and len(cache) > maxsize:
