@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path truncation.
    """
    try:
        # If the object is not an exception, just return its string representation
        if not isinstance(e, BaseException):
            return str(e)

        lines = []

        # Exception header
        lines.append(f"{type(e).__name__}: {e}")

        # Extract traceback information if available
        tb = e.__traceback__
        if tb is not None:
            import traceback
            import os

            frames = traceback.extract_tb(tb)

            # Limit the number of stack frames
            if max_level > 0:
                frames = frames[-max_level:]

            for frame in frames:
                filename = frame.filename

                # Truncate the file path to the last `max_path_level` components
                if max_path_level > 0:
                    parts = filename.split(os.sep)
                    if len(parts) > max_path_level:
                        filename = os.sep.join(['...'] + parts[-max_path_level:])

                lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')

        # Handle chained exceptions (cause)
        cause = e.__cause__
        if cause:
            lines.append("The above exception was the direct cause of the following exception:")
            # Recursively format the cause, but avoid infinite recursion by limiting depth
            lines.append(cls.extostr(cause, max_level, max_path_level))

        return "\n".join(lines)

    except Exception as formatting_error:
        # Fallback in case formatting itself fails
        return f"Error formatting exception: {formatting_error}"

