@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to its default state.
    """
    try:
        import logging
        root = logging.getLogger()
        # Remove all existing handlers
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                # Ignore errors while removing/closing handlers
                pass
        # Reset the root logger level to WARNING
        root.setLevel(logging.WARNING)
        # Reconfigure basicConfig to default settings
        logging.basicConfig(level=logging.WARNING)
    except Exception:
        # Silently ignore any unexpected errors during reset
        pass

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to add a single item to output
    def _add(item):
        # Skip None values
        if item is None:
            return
        # Treat strings and bytes as atomic items
        if isinstance(item, (str, bytes)):
            output.append(item)
            return
        # If item looks like a Declarion (has 'declarations' or 'args')
        if hasattr(item, "declarations") and isinstance(item.declarations, (list, tuple)):
            _normalizeargs(item.declarations, output)
            return
        if hasattr(item, "args") and isinstance(item.args, (list, tuple)):
            _normalizeargs(item.args, output)
            return
        # If item is a tuple of length 2, treat as an implements spec
        if isinstance(item, tuple) and len(item) == 2:
            output.append(item)
            return
        # If item is an iterable (but not a string/bytes), expand it
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
            return
        # Otherwise, treat as a single interface
        output.append(item)

    # If sequence is not iterable (except strings/bytes), treat as single
    if isinstance(sequence, (str, bytes)):
        _add(sequence)
    else:
        try:
            iter(sequence)
        except TypeError:
            _add(sequence)
        else:
            for elem in sequence:
                _add(elem)

    return output

