def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    try:
        # Retrieve current bins and initial value if they exist
        bins = getattr(self, "bins", None)
        initial = getattr(self, "initial_value", None)

        # If an initial value is provided, use it to reset all bins
