                # Preserve the keys, set each value to the initial value
                self.bins = {k: initial for k in bins}
            else:
                # For list/tuple/iterable bins, keep the same length
                length = len(bins) if bins is not None else 0
                self.bins = [initial] * length
        else:
            # No initial value: try to rebuild bins via make_bins()
            make_bins = getattr(self, "make_bins", None)
            if callable(make_bins):
                self.bins = make_bins()
            else:
