def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert bins to a NumPy array for easier manipulation
    bins_arr = np.asarray(bins, dtype=float)

    # Handle empty bins
    if bins_arr.size == 0:
        return 0.0

    # 1D histogram case
    if not isinstance(edges, (list, tuple)):
        edge_arr = np.asarray(edges, dtype=float)
        if edge_arr.ndim != 1:
            raise ValueError("Edges must be a 1D array or list.")
        if edge_arr.size != bins_arr.size + 1:
            raise ValueError("Edges length must be one more than the number of bins.")
        widths = np.diff(edge_arr)
        return float(np.sum(bins_arr * widths))

    # Multi-dimensional histogram case
    if len(edges) != bins_arr.ndim:
        raise ValueError("Number of edge arrays must match the number of dimensions of bins.")

    # Compute widths for each dimension
    widths = []
    for dim, edge in enumerate(edges):
        edge_arr = np.asarray(edge, dtype=float)
        if edge_arr.ndim != 1:
            raise ValueError(f"Edge array at dimension {dim} must be 1D.")
        if edge_arr.size != bins_arr.shape[dim] + 1:
            raise ValueError(
                f"Edge array at dimension {dim} must have length {bins_arr.shape[dim] + 1}."
            )
        widths.append(np.diff(edge_arr))

    # Compute the product of widths for each bin
    prod_widths = np.ones_like(bins_arr, dtype=float)
    for dim, w in enumerate(widths):
        shape = [1] * bins_arr.ndim
        shape[dim] = w.size
        prod_widths *= w.reshape(shape)

    return float(np.sum(bins_arr * prod_widths))

