def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        import re
    except ImportError as exc:
        raise RuntimeError("Regular expression module not available") from exc

    global _RESOURCE_NAME_REGEX
    try:
        return _RESOURCE_NAME_REGEX
    except NameError:
        # Kubernetes-like resource name: lowercase alphanumerics and hyphens,
        # must start and end with an alphanumeric, length 1-253.
        pattern_str = r'^(?=.{1,253}$)[a-z0-9]([-a-z0-9]*[a-z0-9])?$'
        try:
            _RESOURCE_NAME_REGEX = re.compile(pattern_str)
        except re.error as exc:
            raise ValueError(f"Failed to compile resource name regex: {exc}") from exc
        return _RESOURCE_NAME_REGEX

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    # Ensure key is a string
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")

    # Key must not be empty
    if not key:
        raise ValidationError("Key cannot be empty")

    # Allowed characters: letters, digits, hyphen, underscore
    for ch in key:
        if not (ch.isalnum() or ch in "-_"):
            raise ValidationError(f"Invalid character in key: {ch!r}")

    # Length constraints (example: 1-255 characters)
    if len(key) > 255:
        raise ValidationError("Key is too long (maximum 255 characters)")

    # Key cannot start or end with hyphen or underscore
    if key[0] in "-_" or key[-1] in "-_":
        raise ValidationError("Key cannot start or end with hyphen or underscore")

    # No consecutive hyphens or underscores
    if "--" in key or "__" in key:
        raise ValidationError("Key cannot contain consecutive hyphens or underscores")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
