            if field in manifest_dict:
                result[field] = manifest_dict[field]

        # Handle metadata subfields
        metadata = manifest_dict.get("metadata")
        if isinstance(metadata, dict):
            if "metadata" not in result or not isinstance(result["metadata"], dict):
                result["metadata"] = {}
            for subfield in ("name", "namespace", "labels", "annotations"):
                if subfield in metadata:
                    result["metadata"][subfield] = metadata[subfield]

