    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation
    if app is None:
        return
    spec = getattr(app, "spec", None)
    if spec is None:
        return

    # Ensure manifest is iterable
    manifest = getattr(spec, "manifest", None)
    if not isinstance(manifest, (list, tuple)):
        return

    # Ensure observer_schema is a dict; create if missing
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(spec, "observer_schema", observer_schema)
    elif not isinstance(observer_schema, dict):
        # If it's not a dict, we cannot safely modify it; skip generation
        return

    # Helper to extract kind from a resource
    def _get_kind(resource):
        if resource is None:
            return None
        if isinstance(resource, dict):
            return resource.get("kind")
        return getattr(resource, "kind", None)

    # Default schema to apply when none is specified
    default_schema = ["metadata.name", "metadata.namespace", "status"]

    # Iterate over resources and add default schema where needed
    for resource in manifest:
        kind = _get_kind(resource)
        if not kind:
            continue
        if kind not in observer_schema:
            observer_schema[kind] = default_schema.copy()
    # No explicit return value needed; the function mutates app.spec.observer_schema in place.

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    return f"{prefix}{str(status)}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Attempt to retrieve the log from common attribute names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)
    if log is None:
        return ''
    # Ensure we can iterate over the log
    try:
        entries = list(log)
    except TypeError:
        # If log is not iterable, treat as empty
        return ''
    lines = []
    for entry in entries:
        # If entry is a tuple of two items, format as key: value
        if isinstance(entry, tuple) and len(entry) == 2:
            key, value = entry
            line = f"{key}: {value}"
        else:
            line = str(entry)
        if prefix:
            line = f"{prefix}{line}"
        lines.append(line)
    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if not manifest_files:
        return
    if digests_used is None:
        digests_used = set()
    else:
        digests_used = set(digests_used)

    # Extract digests from manifest_files
    try:
        if isinstance(manifest_files, dict):
            manifest_digests = list(manifest_files.values())
        else:
            # Assume iterable of (key, digest) tuples or objects with .digest
            manifest_digests = []
            for item in manifest_files:
                if isinstance(item, tuple) and len(item) == 2:
                    manifest_digests.append(item[1])
                elif hasattr(item, 'digest'):
                    manifest_digests.append(item.digest)
                else:
                    raise TypeError("manifest_files items must be (key, digest) tuples or objects with a 'digest' attribute")
    except Exception as e:
        raise ValueError(f"Failed to extract digests from manifest_files: {e}")

    # Find missing digests
    missing = [d for d in manifest_digests if d not in digests_used]
    if missing:
        # Remove duplicates for clearer error message
        unique_missing = sorted(set(missing))
        raise ValueError(f"Missing digests used: {', '.join(unique_missing)}")
    # No return value needed; success is indicated by no exception.

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and None checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure both objects have a 'version' attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both objects must have a 'version' attribute")
    self_version = getattr(self, "version")
    prior_version = getattr(prior, "version")
    if self_version is None or prior_version is None:
        raise ValueError("version attributes cannot be None")

    # Compare versions; they must be comparable
    try:
        if prior_version >= self_version:
            raise ValueError(
                f"prior.version ({prior_version}) must be less than self.version ({self_version})"
            )
    except TypeError as exc:
        raise TypeError("version attributes must be comparable") from exc

    # Optional: ensure same identifier (e.g., id or name)
    for attr in ("id", "name"):
        if hasattr(self, attr) and hasattr(prior, attr):
            if getattr(self, attr) != getattr(prior, attr):
                raise ValueError(
                    f"prior.{attr} ({getattr(prior, attr)}) does not match self.{attr} ({getattr(self, attr)})"
                )

    # Check that prior's inventory is a subset of self's inventory if both have it
    if hasattr(self, "inventory") and hasattr(prior, "inventory"):
        try:
            self_inv = set(self.inventory)
            prior_inv = set(prior.inventory)
        except TypeError as exc:
            raise TypeError("inventory attributes must be iterable") from exc
        if not prior_inv.issubset(self_inv):
            raise ValueError("prior.inventory must be a subset of self.inventory")

    # Check that prior's items are a subset of self's items if both have it
    if hasattr(self, "items") and hasattr(prior, "items"):
        try:
            self_items = set(self.items)
            prior_items = set(prior.items)
        except TypeError as exc:
            raise TypeError("items attributes must be iterable") from exc
        if not prior_items.issubset(self_items):
            raise ValueError("prior.items must be a subset of self.items")

    # If all checks pass, return None (validation succeeded)
    return None

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(version, (int, str)):
        raise ValueError("version must be an int or str")
    try:
        target_version = int(version)
    except Exception:
        raise ValueError("version must be convertible to int")

    # Helper to iterate over entries
    def iter_entries(inv):
        if isinstance(inv, dict):
            # Assume dict of logical_path -> list of entries
            for val in inv.values():
                if isinstance(val, list):
                    for e in val:
                        if isinstance(e, dict):
                            yield e
                elif isinstance(val, dict):
                    yield val
        elif isinstance(inv, list):
            for e in inv:
                if isinstance(e, dict):
                    yield e
        else:
            # Unsupported structure
            return

    # First pass: collect entries for the target version
    logical_map = {}
    for entry in iter_entries(inventory):
        try:
            entry_version = int(entry.get("version", None))
        except Exception:
            continue
        if entry_version != target_version:
            continue
        logical_path = entry.get("logical_path")
        content_file = entry.get("content_file")
        if logical_path is None or content_file is None:
            continue
        logical_map.setdefault(logical_path, set()).add(content_file)

    # Second pass: include duplicates from later versions
    for entry in iter_entries(inventory):
        dup_of = entry.get("duplicate_of")
        if not dup_of:
            continue
        content_file = entry.get("content_file")
        if content_file is None:
            continue
        if dup_of in logical_map:
            logical_map[dup_of].add(content_file)

    return logical_map

def add_rendition(self, lang, file_path):
    """
    Adds or updates a rendition mapping for the given language.
    The mapping is stored in an attribute named 'renditions' or 'renditions_map'.
    Example:
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
    """
    # Validate language key
    if not isinstance(lang, str) or not lang:
        raise TypeError("lang must be a non-empty string")
    # Validate file path
    if not isinstance(file_path, str) or not file_path:
        raise TypeError("file_path must be a non-empty string")
    # Determine the renditions dictionary
    if hasattr(self, 'renditions'):
        renditions = self.renditions
    elif hasattr(self, 'renditions_map'):
        renditions = self.renditions_map
    else:
        renditions = {}
        # Prefer setting 'renditions' attribute
        setattr(self, 'renditions', renditions)
    # Add or update the mapping
    renditions[lang] = file_path

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if not result:
            continue
        # If result is a list (common for XPath)
        if isinstance(result, list):
            if not result:
                continue
            first = result[0]
            # If the first item is a string (e.g., text() or string() XPath)
            if isinstance(first, str):
                return first
            # If the first item is an element (lxml or ElementTree)
            if hasattr(first, 'text'):
                text = first.text
                if text is None:
                    # Try to concatenate all descendant text
                    try:
                        text = ''.join(first.itertext())
                    except Exception:
                        text = ''
                return text
            # Fallback: return the first item as is
            return first
        # If result is not a list, return it directly
        return result
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    import functools

    @functools.wraps(namefunc)
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 2, ensure the result is a bytestring
        if sys.version_info[0] < 3:
            # In Python 2, unicode type exists
            try:
                unicode_type = unicode
            except NameError:
                unicode_type = str  # fallback, though this branch won't be hit in Py3
            if isinstance(result, unicode_type) and not isinstance(result, bytes):
                # Encode using the default encoding
                return result.encode(sys.getdefaultencoding())
        # In Python 3 or if result is already bytes, return as is
        return result

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess
    import sys

    # Helper to get package name
    pkg_name = __package__ or __name__
    if pkg_name and '.' in pkg_name:
        pkg_name = pkg_name.split('.')[0]

    # Try to get version via importlib.metadata (Python 3.8+)
    version = None
    try:
        try:
            from importlib.metadata import version as get_version
        except Exception:
            from importlib_metadata import version as get_version  # type: ignore
        try:
            version = get_version(pkg_name)
        except Exception:
            version = None
    except Exception:
        version = None

    # Fallback to pkg_resources if available
    if version is None:
        try:
            from pkg_resources import get_distribution
            try:
                version = get_distribution(pkg_name).version
            except Exception:
                version = None
        except Exception:
            version = None

    if not version:
        version = "0.0.0"

    # Get git commit hash
    commit = None
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        )
        commit = result.stdout.strip()
    except Exception:
        commit = None

    # Get git branch name
    branch = None
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        )
        branch = result.stdout.strip()
    except Exception:
        branch = None

    return {"version": version, "commit": commit, "branch": branch}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate style
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")
    style = style.lower()

    # Helper to convert a component to string, handling None
    def _comp_to_str(c):
        if c is None:
            return None
        if isinstance(c, (list, tuple)):
            # Join list/tuple components with '.'
            return ".".join(str(x) for x in c if x is not None)
        return str(c)

    # Parse pieces into components
    major = minor = patch = pre = build = None

    if isinstance(pieces, dict):
        major = _comp_to_str(pieces.get("major"))
        minor = _comp_to_str(pieces.get("minor"))
        patch = _comp_to_str(pieces.get("patch"))
        pre   = _comp_to_str(pieces.get("pre"))
        build = _comp_to_str(pieces.get("build"))
    elif isinstance(pieces, (list, tuple)):
        # Filter out None values
        filtered = [c for c in pieces if c is not None]
        if len(filtered) >= 1:
            major = _comp_to_str(filtered[0])
        if len(filtered) >= 2:
            minor = _comp_to_str(filtered[1])
        if len(filtered) >= 3:
            patch = _comp_to_str(filtered[2])
        if len(filtered) >= 4:
            pre = _comp_to_str(filtered[3])
        if len(filtered) >= 5:
            build = _comp_to_str(filtered[4])
    elif isinstance(pieces, str):
        # Assume it's already a full version string
        return pieces
    elif isinstance(pieces, (int, float)):
        major = _comp_to_str(pieces)
    else:
        raise TypeError(f"Unsupported type for pieces: {type(pieces).__name__}")

    # Ensure major, minor, patch are present
    if major is None:
        raise ValueError("Major version component is required")
    if minor is None:
        minor = "0"
    if patch is None:
        patch = "0"

    # Build the base version string
    base = f"{major}.{minor}.{patch}"

    # Handle styles
    if style == "semver":
        version = base
        if pre:
            version += f"-{pre}"
        if build:
            version += f"+{build}"
        return version
    elif style == "pep440":
        version = base
        if pre:
            # PEP 440 uses a dot before pre-release
            version += f".{pre}"
        if build:
            version += f"+{build}"
        return version
    elif style == "git":
        version = f"v{base}"
        if pre:
            version += f"-{pre}"
        if build:
            version += f"+{build}"
        return version
    elif style == "none":
        return base
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise ValueError("pieces cannot be None")
    try:
        # Convert to iterable of strings
        iterable = list(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")
    for item in iterable:
        try:
            if '+' in str(item):
                return '.'
        except Exception:
            # If conversion to string fails, skip this item
            continue
    return '+'

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate parameter types
    for name, val in (('validate_objects', validate_objects),
                      ('check_digests', check_digests),
                      ('show_warnings', show_warnings)):
        if not isinstance(val, bool):
            raise TypeError(f"{name} must be a bool, got {type(val).__name__}")

    # Retrieve the collection of objects to validate
    objects = getattr(self, 'objects', None)
    if objects is None:
        objects = getattr(self, '_objects', None)
    if objects is None:
        raise AttributeError("Instance has no 'objects' or '_objects' attribute")

    # Ensure objects is an iterable (but not a string/bytes)
    if isinstance(objects, (str, bytes)):
        raise TypeError("'objects' attribute must be an iterable, not a string or bytes")
    try:
        iter(objects)
    except TypeError as exc:
        raise TypeError("'objects' attribute must be an iterable") from exc

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself
        if validate_objects:
            if hasattr(obj, 'validate'):
                try:
                    result = obj.validate()
                    if result is False:
                        is_valid = False
                except Exception as exc:
                    is_valid = False
                    if show_w

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the root path is defined
    if not hasattr(self, "root_path") or self.root_path is None:
        raise ValueError("root_path attribute must be set before initialization")

    # Import required modules locally to avoid global imports
    from pathlib import Path
    import os

    root = Path(self.root_path)

    # If the root already exists, ensure it is empty
    if root.exists():
        if not root.is_dir():
            raise ValueError(f"root_path '{root}' exists but is not a directory")
        # Check if directory is empty
        if any(root.iterdir()):
            raise ValueError(f"root_path '{root}' already exists and is not empty")
    else:
        try:
            root.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise RuntimeError(f"Failed to create root directory '{root}': {exc}") from exc

    # Define standard OCFL subdirectories
    subdirs = [
        ".ocfl_root",
        ".ocfl_objects",
        ".ocfl_metadata",
        ".ocfl_version",
    ]

    # Create subdirectories
    for sub in subdirs:
        sub_path = root / sub
        try:
            sub_path.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create subdirectory '{sub_path}': {exc}") from exc

    # Create the .ocfl_version file with the current OCFL version
    version_file = root / ".ocfl_version" / "version.txt"
    try:
        version_file.parent.mkdir(parents=True, exist_ok=True)
        version_file.write_text("1.0\n", encoding="utf-8")
    except OSError as exc:
        raise RuntimeError(f"Failed to write OCFL version file '{version_file}': {exc}") from exc

    # Optionally, set permissions to read/write for the owner only
    try:
        os.chmod(root, 0o700)
        for sub in subdirs:
            os.chmod(root / sub, 0o700)
    except OSError:
        # Permissions change is non-critical; ignore failures
        pass

    # Store a flag indicating initialization succeeded
    self._initialized = True
    return None

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        if not version_dirs:
            # Nothing to validate; return empty record
            self.different_digests = {}
            return {}

        # Ensure we have a root inventory to compare against
        root_inv = getattr(self, "root_inventory", None)
        if root_inv is None:
            raise AttributeError("self.root_inventory is required for comparison")
        if not isinstance(root_inv, dict):
            raise TypeError("self.root_inventory must be a dict mapping file paths to digests")

        # Prepare a container for differences
        differences = {}

        for dir_name in version_dirs:
            # Build path to the inventory file
            inv_path = os.path.join(dir_name, "inventory.json")
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(f"Missing inventory file in version directory '{dir_name}'")

            # Load the inventory
            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inv_data = json.load(f)
            except Exception as exc:
                raise ValueError(f"Failed to load inventory from '{inv_path}': {exc}")

            if not isinstance(inv_data, dict):
                raise ValueError(f"Inventory in '{inv_path}' is not a dict")

            # Compare digests with the root inventory
            diff_files = []
            for file_path, digest in inv_data.items():
                root_digest = root_inv.get(file_path)
                if root_digest is None or root_digest != digest:
                    diff_files.append(file_path)

            if diff_files:
                differences[dir_name] = diff_files

        # Store the differences for later validation steps
        self.different_digests = differences
        return differences

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list) and all(
            isinstance(v, tuple) for v in node.value
        )

    # Recursive merge of two mapping nodes; modifies node1 in place and returns it
    def merge_mapping_nodes(node1, node2):
        if not (is_mapping_node(node1) and is_mapping_node(node2)):
            return node2  # if either is not a mapping, the second wins
        # Build a dict of key string to (key_node, value_node) preserving order of node1
        merged = {}
        order = []
        for k_node, v_node in node1.value:
            key = getattr(k_node, 'value', None)
            merged[key] = (k_node, v_node)
            order.append(key)
        for k_node, v_node in node2.value:
            key = getattr(k_node, 'value', None)
            if key in merged:
                existing_k, existing_v = merged[key]
                if is_mapping_node(existing_v) and is_mapping_node(v_node):
                    merged[key] = (existing_k, merge_mapping_nodes(existing_v, v_node))
                else:
                    merged[key] = (k_node, v_node)  # last wins
            else:
                merged[key] = (k_node, v_node)
                order.append(key)
        # Reconstruct node1.value preserving order
        node1.value = [(merged[k][0], merged[k][1]) for k in order]
        return node1

    result = []
    key_index = {}  # key string -> index in result list
    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            # Skip nodes without a proper key
            continue
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_value_node = result[idx]
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                merged_node = merge_mapping_nodes(existing_value_node, value_node)
                result[idx] = (existing_key_node, merged_node)
            else:
                # last wins
                result[idx] = (existing_key_node, value_node)
        else:
            result.append((key_node, value_node))
            key_index[key] = len(result) - 1
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation of the parser argument
    if parser is None:
        raise TypeError("parser must not be None")
    # Ensure the object looks like an argparse.ArgumentParser
    if not hasattr(parser, 'add_argument') or not hasattr(parser, '_actions'):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # Skip subparser actions (they don't represent flags themselves)
        if action.__class__.__name__ == '_SubParsersAction':
            continue
        # Only include actions that actually have option strings
        if getattr(action, 'option_strings', None):
            flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode (i.e., its value is a list of key/value tuples)
    def is_mapping_node(node):
        try:
            return isinstance(node.value, list)
        except AttributeError:
            return False

    # Recursive merge of mapping node values
    def merge_mapping_values(existing, new):
        # existing and new are MappingNode instances
        # Merge their value lists
        merged = deep_merge_nodes(existing.value + new.value)
        # Create a new MappingNode preserving the tag of the existing node
        try:
            return type(existing)(existing.tag, merged)
        except Exception:
            # Fallback: try to construct with tag and value
            return type(existing)(existing.tag, merged)

    result = []
    key_index = {}  # maps key string to index in result list

    for key_node, value_node in nodes:
        # key_node is expected to be a ScalarNode
        try:
            key_str = key_node.value
        except AttributeError:
            # If key_node doesn't have a 'value', skip this entry
            continue

        if key_str not in key_index:
            # First occurrence: add to result
            result.append((key_node, value_node))
            key_index[key_str] = len(result) - 1
        else:
            # Duplicate key: merge with existing
            idx = key_index[key_str]
            _, existing_value = result[idx]

            if is_mapping_node(existing_value) and is_mapping_node(value_node):
                # Both are mapping nodes: deep merge
                merged_node = merge_mapping_values(existing_value, value_node)
                result[idx] = (key_node, merged_node)
            else:
                # Non-mapping or one is not mapping: last wins
                result[idx] = (key_node, value_node)

    return result

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError("argparse module is required to build parsers") from exc

    try:
        parser = argparse.ArgumentParser(description='Top-level parser')
    except Exception as exc:
        raise RuntimeError("Failed to create ArgumentParser") from exc

    # Create subparsers; use 'required' if supported (Python 3.7+)
    try:
        subparsers = parser.add_subparsers(dest='command', required=True)
    except TypeError:
        # 'required' argument not supported in older Python versions
        subparsers = parser.add_subparsers(dest='command')

    return parser, subparsers

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("The argument must be an iterable of dictionaries") from None

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float, complex)):
                raise TypeError(f"Dictionary values must be numeric, got {type(value).__name__} for key {key!r}")
            result[key] = result.get(key, 0) + value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        # Strip whitespace and convert to lowercase for comparison
        cleaned = val.strip().lower()
        # Common textual representations of None
        return cleaned in {"none", "null", "nil"}
    except Exception:
        # In case of unexpected errors, return False
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        # Some actions (e.g., positional arguments) may not have option_strings
        option_strings = getattr(action, 'option_strings', None)
        if not option_strings:
            continue
        for flag in option_strings:
            if flag:  # skip empty strings
                flags.append(flag)
    return ' '.join(flags)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()
    stack = list(cls.__subclasses__())
    while stack:
        sub = stack.pop()
        if sub not in result:
            result.add(sub)
            stack.extend(sub.__subclasses__())
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of inputs
    if not isinstance(string, str):
        raise TypeError(f"Expected string for 'string', got {type(string).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"Expected list or tuple for 'alphabet', got {type(alphabet).__name__}")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols to define a base.")

    # Ensure alphabet symbols are unique
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet contains duplicate symbols, which would make digit mapping ambiguous.")

    # Build a mapping from symbol to its numeric value
    symbol_to_value = {symbol: idx for idx, symbol in enumerate(alphabet)}

    # Handle empty string as zero
    if string == "":
        return 0

    result = 0
    for ch in string:
        if ch not in symbol_to_value:
            raise ValueError(f"Character '{ch}' not found in the provided alphabet.")
        result = result * base + symbol_to_value[ch]

    return result

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or "always" (case-insensitive)
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
        if freq_str.lower() == "always":
            return None
    else:
        # Non-string input is invalid
        raise ValueError(f"Frequency must be a string, got {type(frequency).__name__}")

    # Split into number and unit
    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency '{frequency}' is not in the expected 'number unit' format")

    number_str, unit = parts
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Frequency number '{number_str}' is not an integer")

    # Normalize unit: strip trailing 's' for plurals
    unit = unit.lower()
    if unit.endswith('s'):
        unit = unit[:-1]

    # Map unit to timedelta keyword
    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds'
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit '{unit}' in frequency '{frequency}'")

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows environment
        if os.name != 'nt':
            return False

        # Git Bash sets OSTYPE to 'msys' or 'cygwin'
        ostype = os.getenv('OSTYPE', '').lower()
        if ostype.startswith('msys') or ostype.startswith('cygwin'):
            return True

        # Some Git Bash installations set MSYSTEM (e.g., MINGW64)
        if os.getenv('MSYSTEM'):
            return True

        # As a fallback, check for common Git Bash indicators
        term = os.getenv('TERM', '').lower()
        if term in ('xterm', 'xterm-256color'):
            # Ensure we are on Windows
            if os.getenv('MSYSTEM') or 'msys' in ostype:
                return True

        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # If file exists and we are not allowed to overwrite, abort
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Ensure parent directories exist
    parent_dir = os.path.dirname(os.path.abspath(config_filename))
    if parent_dir and not os.path.isdir(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for '{config_filename}': {exc}") from exc

    # Write the file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set the file mode
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Helper to resolve a name and optional default
    def _resolve(name, default_provided, default_value):
        if not isinstance(name, str) or not name:
            raise ValueError("Environment variable name must be a non-empty string")
        value = os.getenv(name)
        if value is None:
            if default_provided:
                return default_value
            raise KeyError(f"Environment variable '{name}' is not set and no default value provided")
        return value

    # Determine the type of matcher
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 0:
            raise ValueError("Matcher must contain at least a variable name")
        if len(matcher) > 2:
            raise ValueError("Matcher can contain at most a variable name and a default value")
        name = matcher[0]
        if len(matcher) == 2:
            default_provided = True
            default_value = matcher[1]
        else:
            default_provided = False
            default_value = None
        return _resolve(name, default_provided, default_value)

    if isinstance(matcher, str):
        # Split on the first colon to separate name and default
        parts = matcher.split(":", 1)
        name = parts[0].strip()
        if len(parts) == 2:
            default_provided = True
            default_value = parts[1]
        else:
            default_provided = False
            default_value = None
        return _resolve(name, default_provided, default_value)

    # Unsupported matcher type
    raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")

    # Build the command
    if isinstance(commands, str):
        # Use shell execution for string commands
        cmd_str = commands
        if args:
            # Escape arguments for shell
            import shlex
            cmd_str += " " + " ".join(shlex.quote(arg) for arg in args)
        cmd = cmd_str
        shell = True
    else:
        # List of command parts
        if not commands:
            raise ValueError("commands list cannot be empty")
        cmd = commands + args
        shell = False

    # Prepare subprocess parameters
    kwargs = {
        "cwd": cwd,
        "env": env,
        "stdout": subprocess.PIPE,
        "stderr": subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
        "text": True,
        "shell": shell,
    }

    if verbose:
        print(f"Running command: {cmd if isinstance(cmd, str) else ' '.join(cmd)}")

    try:
        result = subprocess.run(cmd, **kwargs, check=True)
    except subprocess.CalledProcessError as e:
        # Capture stderr if not hidden
        err_output = e.stderr if not hide_stderr else ""
        msg = f"Command '{cmd}' failed with exit code {e.returncode}"
        if err_output:
            msg += f": {err_output.strip()}"
        raise RuntimeError(msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{cmd}': {e}") from e

    if verbose:
        print(f"Command output:\n{result.stdout}")

    return result.stdout.strip()

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        # If it's already an IPv4Address instance, it's valid
        if isinstance(target, ipaddress.IPv4Address):
            return True
        # Try to parse the target; ip_address accepts strings, bytes, or integers
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        # Any error (e.g., ValueError, TypeError) means it's not a valid IPv4 address
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            # Use safe_dump for a safe, unicode-friendly representation
            return yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True,
            )
        else:
            # Allow a custom Dumper if provided
            return yaml.dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True,
            )
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc
    except Exception as exc:
        # Catch any other unexpected errors and wrap them
        raise ValueError(f"Unexpected error during YAML dump: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize shape
    if isinstance(shape, (list, tuple)):
        try:
            shape_tuple = tuple(int(dim) for dim in shape)
        except Exception as exc:
            raise TypeError("Shape must be a tuple or list of integers") from exc
    else:
        raise TypeError("Shape must be a tuple or list of integers")

    if any(dim < 0 for dim in shape_tuple):
        raise ValueError("Shape dimensions must be non-negative")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be a valid numpy dtype") from exc

    # Create the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise ValueError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    configs = {}
    error_records = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(obj):
        if isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_vars(v) for v in obj]
        elif isinstance(obj, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, obj)
        else:
            return obj

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f"JSON decode error in file '{fname}': {e}"
                    record = logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None)
                    error_records.append(record)
                    continue
            if not isinstance(data, dict):
                msg = f"Configuration in file '{fname}' is not a JSON object (dict)."
                record = logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None)
                error_records.append(record)
                continue
            if resolve_env:
                data = resolve_env_vars(data)
            if overrides:
                # shallow merge: overrides take precedence
                merged = data.copy()
                merged.update(overrides)
                data = merged
            configs[fname] = data
        except FileNotFoundError as e:
            msg = f"File not found: '{fname}'."
            record = logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None)
            error_records.append(record)
        except Exception as e:
            msg = f"Unexpected error loading file '{fname}': {e}"
            record = logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

