def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache exists and is not empty
    if not hasattr(self, "cache") or not self.cache:
        raise KeyError("popitem(): dictionary is empty")

    # Determine the frequency dictionary if it exists
    freq_dict = getattr(self, "freq", {})

    # Find the key with the smallest frequency
    min_key = None
    min_freq = None
    for k in self.cache:
        f = freq_dict.get(k, 0)
        if min_freq is None or f < min_freq:
            min_freq = f
            min_key = k

    # Remove the key from the main cache
    value = self.cache.pop(min_key)

    # Remove the key from the frequency dictionary if present
    if min_key in freq_dict:
        del freq_dict[min_key]

    # If a frequency table exists, remove the key from it
    if hasattr(self, "freq_table"):
        ft = self.freq_table
        if min_freq in ft:
            ft[min_freq].pop(min_key, None)
            if not ft[min_freq]:
                del ft[min_freq]
        # Update the stored minimum frequency if needed
        if hasattr(self, "min_freq"):
            if self.min_freq == min_freq:
                if ft:
                    self.min_freq = min(ft.keys())
                else:
                    self.min_freq = None

    # If the stored value is a tuple of (actual_value, freq), return only the value
    if isinstance(value, tuple) and len(value) == 2:
        return (min_key, value[0])
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Determine the underlying storage attribute
    storage = None
    if hasattr(self, "_cache"):
        storage = self._cache
    elif hasattr(self, "_data"):
        storage = self._data
    else:
        raise AttributeError("LRUCache has no storage attribute to pop from")

    # Attempt to pop the least‑recently used item
    try:
        # OrderedDict supports popitem(last=False) for LRU
        return storage.popitem(last=False)
    except TypeError:
        # The storage does not accept the 'last' keyword (e.g., a plain dict)
        # In that case we cannot guarantee LRU order; raise a clear error
        raise NotImplementedError(
            "Underlying storage does not support popitem(last=False) for LRU removal"
        )
    except KeyError:
        # The cache is empty
        raise KeyError("popitem from an empty LRUCache")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to locate the underlying storage that behaves like a dict
    storage = getattr(self, "_data", None)
    if storage is None:
        storage = getattr(self, "data", None)
    if storage is None:
        raise AttributeError("popitem() called on object without a dict-like attribute")
    try:
        return storage.popitem()
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches either "in: param" or "in(param)" where param is a word.
        pattern = re.compile(
            r'\bin\s*:\s*(?P<param>\w+)|\bin\s*\(\s*(?P<param>\w+)\s*\)'
        )
        return pattern
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style parameter regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Attempt to retrieve a style attribute if it exists
        style = getattr(self, "_param_style", None)

        # Try to instantiate the converter with the style if provided
        if style is not None:
            try:
                converter = _converting._Converter(style)
                if isinstance(converter, _converting._Converter):
                    return converter
            except TypeError:
                # Converter may not accept a style argument; fall back below
                pass

        # Fallback: instantiate without arguments
        converter = _converting._Converter()
        if not isinstance(converter, _converting._Converter):
            raise TypeError("Converter instance is not of expected type")
        return converter

    except Exception as exc:
        raise RuntimeError(f"Failed to create parameter style converter: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Handle mapping types (e.g., dict)
        if isinstance(request, dict):
            # Check for explicit flags
            if request.get("public"):
                return True
            if request.get("private"):
                return True
            if request.get("legacy"):
                return True
            # Check a type field
            if request.get("type") in ("public", "private", "legacy"):
                return True

        # Handle objects with attributes
        if hasattr(request, "public") and getattr(request, "public"):
            return True
        if hasattr(request, "private") and getattr(request, "private"):
            return True
        if hasattr(request, "legacy") and getattr(request, "legacy"):
            return True
        if hasattr(request, "type") and getattr(request, "type") in ("public", "private", "legacy"):
            return True

        return False
    except Exception:
        # In case of any unexpected error, treat as not a Diaspora request
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    A Matrix request typically has a URL path that starts with '/_matrix'.
    This function attempts to detect that pattern in a variety of request
    object shapes (Flask, Django, FastAPI, or a plain dict).  It returns
    True if the request appears to be a Matrix request, otherwise False.
    """
    try:
        if request is None:
            return False

        # Extract the path component from the request object
        path = None

        # Common attribute names for the request path
        if hasattr(request, "path"):
            path = getattr(request, "path")
        elif hasattr(request, "url"):
            path = getattr(request, "url")
        elif isinstance(request, dict):
            path = request.get("path") or request.get("url")

        if not path:
            return False

        # Ensure we are working with a string
        if not isinstance(path, str):
            try:
                path = str(path)
            except Exception:
                return False

        # If the path looks like a full URL, strip the scheme and netloc
        if "://" in path:
            try:
                from urllib.parse import urlparse

                parsed = urlparse(path)
                path = parsed.path
            except Exception:
                # If parsing fails, fall back to the original string
                pass

        # Normalize the path: remove leading/trailing whitespace
        path = path.strip()

        # Matrix requests start with '/_matrix'
        return path.startswith("/_matrix") or "/_matrix" in path
    except Exception:
        # Any unexpected error is treated as a non-Matrix request
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Handle None input gracefully
    if node is None:
        return {}

    # Ensure the node is iterable (e.g., an ElementTree.Element)
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("Provided node is not iterable or not a valid XML element") from exc

    # Build the dictionary mapping tag names to child elements
    result = {}
    for child in children:
        # child.tag may contain namespace; keep it as is
        result[child.tag] = child

    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate url
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Validate document_path
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Default document path if not provided or empty
    if not document_path:
        document_path = "/nodeinfo/2.0"

    # Normalize paths: remove trailing slash from base url and leading slash from document path
    base = url.rstrip("/")
    path = document_path.lstrip("/")

    href = f"{base}/{path}"

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict):
            return data
        # If JSON is not a dict, wrap it
        return {"data": data}
    except Exception:
        pass

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET

        def _local_name(tag: str) -> str:
            return tag.split("}")[-1] if "}" in tag else tag

        root = ET.fromstring(document)
        result: Dict[str, any] = {}

        # Subject
        subject_elem = root.find(".//{*}Subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text.strip()

        # Aliases
        aliases = []
        for alias_elem in root.findall(".//{*}Alias"):
            if alias_elem.text:
                aliases.append(alias_elem.text.strip())
        if aliases:
            result["aliases"] = aliases

        # Links
        links = []
        for link_elem in root.findall(".//{*}Link"):
            link_dict: Dict[str, str] = {}
            # Attributes
            for attr in ["rel", "type", "href", "template", "title"]:
                if attr in link_elem.attrib:
                    link_dict[attr] = link_elem.attrib[attr]
            # If no attributes but text present
            if not link_dict and link_elem.text:
                link_dict["href"] = link_elem.text.strip()
            if link_dict:
                links.append(link_dict)
        if links:
            result["links"] = links

        if result:
            return result
        else:
            raise ValueError("No recognizable data found in XRD document")
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger document: {e}") from e

