def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests

        # Basic input validation
        if not isinstance(url, str):
            raise TypeError("url must be a string")
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number")
        if timeout <= 0:
            raise ValueError("timeout must be positive")
        if not isinstance(method, str):
            raise TypeError("method must be a string")

        # Send the request
        response = requests.request(
            method=method,
            url=url,
            data=data,
            timeout=timeout,
            *args,
            **kwargs
        )
        return (response.status_code, None)
    except Exception as exc:
        # Return None for status code and the exception instance
        return (None, exc)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Validate inputs
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    for k in keys:
        if not isinstance(k, str):
            raise TypeError("all keys must be strings")

    current = dic
    all_keys = [key] + list(keys)

    for i, k in enumerate(all_keys):
        if i == len(all_keys) - 1:
            # last key: set the value
            current[k] = val
        else:
            # intermediate keys: ensure a dict exists
            if k not in current:
                current[k] = {}
            elif not isinstance(current[k], dict):
                raise TypeError(f"Cannot create nested key '{k}' because existing value is not a dict")
            current = current[k]

    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    # Validate settings_dirs
    if not isinstance(settings_dirs, (list, tuple, set)):
        raise TypeError("settings_dirs must be an iterable of directory paths")
    # Validate spec_option
    if spec_option is not None and not isinstance(spec_option, (str, callable)):
        raise TypeError("spec_option must be a string pattern, a callable, or None")

    file_names = []

    for dir_path in settings_dirs:
        # Skip non-string entries
        if not isinstance(dir_path, str):
            continue
        # Skip if not a directory
        if not os.path.isdir(dir_path):
            continue

        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue

                # No filter: include all files
                if spec_option is None:
                    file_names.append(full_path)
                # String pattern: use fnmatch
                elif isinstance(spec_option, str):
                    if fnmatch.fnmatch(entry, spec_option):
                        file_names.append(full_path)
                # Callable filter
                elif callable(spec_option):
                    try:
                        if spec_option(entry):
                            file_names.append(full_path)
                    except Exception:
                        # If the filter raises an exception, skip this file
                        continue
        except (PermissionError, OSError):
            # Skip directories that cannot be accessed
            continue

    # Return a sorted list for deterministic ordering
    return sorted(file_names)

