        """Gets the plugin manager."""
        # Lazy initialization of a simple plugin manager.
        if not hasattr(cls, "_plugin_manager"):
            # Define a minimal PluginManager if one does not exist.
            class _PluginManager:
                def __init__(self):
                    self._plugins = {}

                def register(self, name, plugin):
                    """Register a plugin under the given name."""
                    if not isinstance(name, str):
                        raise TypeError("Plugin name must be a string")
                    if name in self._plugins:
                        raise KeyError(f"Plugin '{name}' is already registered")
                    self._plugins[name] = plugin

                def get(self, name):
                    """Retrieve a registered plugin by name."""
                    return self._plugins.get(name)

                def list_plugins(self):
                    """Return a list of registered plugin names."""
                    return list(self._plugins.keys())

            cls._plugin_manager = _PluginManager()
        return cls._plugin_manager

@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Define the mandatory fields that a valid spec must contain.
        # These are typical for an IR specification; adjust as needed.
        required_fields = {"name", "version", "description", "spec"}

        # Helper to raise a consistent exception
        def _raise_missing(fields):
            missing = ", ".join(sorted(fields))
            raise IRValidatorException(
                f"Missing mandatory field(s) in spec: {missing}"
            )

        # Validate input presence
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # If the content is already a dictionary, use it directly.
        if isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            # Assume string or bytes; attempt to parse as YAML.
            try:
                # Import yaml lazily to avoid unnecessary dependency if not used.
                import yaml
                if isinstance(spec_content, bytes):
                    spec_content = spec_content.decode("utf-8")
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(
                    f"Failed to parse spec content as YAML: {exc}"
                ) from exc

        # Ensure the parsed content is a dictionary.
        if not isinstance(spec_dict, dict):
            raise IRValidatorException(
                f"Spec content must be a mapping, got {type(spec_dict).__name__}"
            )

        # Check for missing mandatory fields.
        missing = required_fields - spec_dict.keys()
        if missing:
            _raise_missing(missing)

        # All checks passed; return the validated spec dictionary.
        return spec_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Retrieve the spec, args, and env dictionaries if they exist
    spec = getattr(self, "spec", {})
    args = getattr(self, "args", {})
    env = getattr(self, "env", {})
    # Ensure spec is a dictionary; if not, return empty defaults
    if not isinstance(spec, dict):
        return defaults
    for name, spec_item in spec.items():
        try:
            # Attempt to extract a default value from the spec item
            if isinstance(spec_item, dict):
                default_val = spec_item.get("default")
            else:
                default_val = getattr(spec_item, "default", None)
            # If no default in spec, fall back to provided args or env
            if default_val is None:
                if name in args:
                    default_val = args[name]
                elif name in env:
                    default_val = env[name]
            defaults[name] = default_val
        except Exception:
            # In case of any unexpected error, skip this argument
            continue
    return defaults

