def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # The parser options are expected to be stored in a dictionary
    # mapping command names to their option specifications.
    # This attribute may be named differently depending on the
    # surrounding code; we try a few common names.
    options_source = None
    for attr in ("_parser_options", "parser_options", "options"):
        if hasattr(self, attr):
            options_source = getattr(self, attr)
            break

    if options_source is None:
        raise AttributeError("No parser options attribute found on the object")

    # Ensure the source is a mapping
    if not isinstance(options_source, dict):
        raise TypeError("Parser options source must be a dictionary")

    # Retrieve the options for the requested command
    try:
        command_options = options_source[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name!r}")

    # The options may be stored as a list, tuple, set, or any iterable.
    # Convert to a list for consistency.
    if isinstance(command_options, (list, tuple, set)):
        return list(command_options)
    try:
        return list(command_options)
    except TypeError:
        raise TypeError(f"Options for command {command_name!r} are not iterable")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Strip whitespace and check for emptiness
    command_name = command_name.strip()
    argument_name = argument_name.strip()
    if not command_name:
        raise ValueError("command_name cannot be empty")
    if not argument_name:
        raise ValueError("argument_name cannot be empty")

    # Attempt to retrieve the command object
    try:
        command = self.commands.get(command_name)
    except AttributeError:
        raise AttributeError("The object does not have a 'commands' attribute")

    # If command not found, try alias mapping if available
    if command is None and hasattr(self, "command_aliases"):
        command = self.command_aliases.get(command_name)

    if command is None:
        # Command not found; return None to indicate missing spec
        return None

    # Retrieve the option specification from the command
    # Support both dict-like and object-like interfaces
    spec = None
    try:
        if isinstance(command, dict):
            spec = command.get(argument_name)
        elif hasattr(command, "options") and isinstance(command.options, dict):
            spec = command.options.get(argument_name)
        elif hasattr(command, "get_option"):
            # Some command objects may expose a get_option method
            spec = command.get_option(argument_name)
    except Exception:
        # Any error retrieving the spec should result in None
        spec = None

    return spec

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary; if None, treat as empty dict
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve required arguments from the instance; if not defined, assume none required
    required = getattr(self, "required_args", None)
    if required is None:
        return True
    if not hasattr(required, "__iter__"):
        raise TypeError(f"required_args must be an iterable, got {type(required).__name__}")

    # Find any missing required arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    def _evaluate(cond, args_dict):
        """Evaluate a single required_when condition."""
        if callable(cond):
            try:
                return bool(cond(args_dict))
            except Exception:
                return False
        if isinstance(cond, str):
            # simple presence or equality check
            if '==' in cond:
                key, val = [c.strip() for c in cond.split('==', 1)]
                return key in args_dict and str(args_dict.get(key)) == val
            else:
                return cond in args_dict
        if isinstance(cond, dict):
            return all(str(args_dict.get(k)) == str(v) for k, v in cond.items())
        if isinstance(cond, list):
            return all(_evaluate(c, args_dict) for c in cond)
        return False

    # Ensure args is a dict-like object
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            args = {}

    required = []
    for opt in options_spec:
        # Retrieve option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        if _evaluate(cond, args):
            required.append(name)

    return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        :raises TypeError: If args is not a mapping.
        :raises ValueError: If any argument value exceeds its specified maximum length.
        """
        # Ensure args is a mapping (dict-like)
        if not isinstance(args, dict):
            raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

        # Retrieve length constraints from the instance, if any
        max_lengths = getattr(self, "lengths", None)
        if max_lengths is None:
            # No length constraints defined; nothing to validate
            return True

        for key, value in args.items():
            # Skip validation for keys without a defined maximum length
            if key not in max_lengths:
                continue

            max_len = max_lengths[key]
            # Skip if max_len is not an integer or is None
            if not isinstance(max_len, int) or max_len is None:
                continue

            # Skip None values (treated as length 0)
            if value is None:
                continue

            try:
                val_len = len(value)
            except TypeError:
                # Value does not support len(); skip or raise error
                raise TypeError(f"Argument '{key}' of type {type(value).__name__} does not support len()")

            if val_len > max_len:
                raise ValueError(
                    f"Argument '{key}' length {val_len} exceeds maximum allowed {max_len}"
                )

        return True

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Ensure args is a mapping
        if not isinstance(args, dict):
            raise TypeError(f"args must be a dict, got {type(args).__name__}")

        # Ensure the instance has an 'arguments' attribute
        if not hasattr(self, "arguments"):
            raise AttributeError("The instance does not have an 'arguments' attribute")

        # Iterate over defined arguments
        for arg_name, definition in self.arguments.items():
            # Skip if no choices defined
            if "choices" not in definition:
                continue

            # Retrieve the value from args; if missing, skip validation
            if arg_name not in args:
                continue

            value = args[arg_name]
            choices = definition["choices"]

            # Normalize choices to a set for efficient lookup
            try:
                choice_set = set(choices)
            except TypeError:
                # If choices is not iterable, treat as single choice
                choice_set = {choices}

            # If the value is a collection (list/tuple/set), validate each element
            if isinstance(value, (list, tuple, set)):
                for elem in value:
                    if elem not in choice_set:
                        raise ValueError(
                            f"Invalid value '{elem}' for argument '{arg_name}'. "
                            f"Expected one of {sorted(choice_set)}."
                        )
            else:
                if value not in choice_set:
                    raise ValueError(
                        f"Invalid value '{value}' for argument '{arg_name}'. "
                        f"Expected one of {sorted(choice_set)}."
                    )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected to be a dict, list, or tuple of numeric values.
    :raises TypeError: If args is not a dict, list, or tuple, or if any value is not numeric.
    :raises AttributeError: If the instance does not have 'min' or 'max' attributes.
    :raises ValueError: If any value is outside the [min, max] range or if min > max.
    :return: True if all values are within the specified bounds.
    """
    # Validate args type
    if args is None:
        raise ValueError("args cannot be None")
    if not isinstance(args, (dict, list, tuple)):
        raise TypeError("args must be a dict, list, or tuple")

    # Retrieve min and max bounds from the instance
    try:
        min_val = self.min
        max_val = self.max
    except AttributeError as exc:
        raise AttributeError("Instance must have 'min' and 'max' attributes") from exc

    # Ensure bounds are numeric and logically consistent
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("'min' and 'max' attributes must be numeric")
    if min_val > max_val:
        raise ValueError(f"min ({min_val}) cannot be greater than max ({max_val})")

    # Determine iterable over arguments
    if isinstance(args, dict):
        iterable = args.items()
    else:
        iterable = enumerate(args)

    # Validate each argument value
    for key, value in iterable:
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument '{key}' value must be numeric, got {type(value).__name__}")
        if value < min_val or value > max_val:
            raise ValueError(
                f"Argument '{key}' value {value} out of bounds [{min_val}, {max_val}]"
            )

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Basic validation of inputs
            if not isinstance(subcommand, str) or not subcommand:
                raise ValueError("subcommand must be a non-empty string")
            if not isinstance(type_name, str) or not type_name:
                raise ValueError("type_name must be a non-empty string")
            if not isinstance(option_name, str) or not option_name:
                raise ValueError("option_name must be a non-empty string")
            if spec_option is None:
                spec_option = {}
            if not isinstance(spec_option, dict):
                raise TypeError("spec_option must be a dictionary")

            # Define a simple complex type class on the fly
            class ComplexArgumentType:
                def __init__(self, subcmd, tname, opt_name, spec):
                    self.subcommand = subcmd
                    self.type_name = tname
                    self.option_name = opt_name
                    self.spec_option = spec

                def __repr__(self):
                    return (
                        f"ComplexArgumentType(subcommand={self.subcommand!r}, "
                        f"type_name={self.type_name!r}, "
                        f"option_name={self.option_name!r}, "
                        f"spec_option={self.spec_option!r})"
                    )

                def __eq__(self, other):
                    if not isinstance(other, ComplexArgumentType):
                        return NotImplemented
                    return (
                        self.subcommand == other.subcommand
                        and self.type_name == other.type_name
                        and self.option_name == other.option_name
                        and self.spec_option == other.spec_option
                    )

            # Create and return the instance
            return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

        except Exception as exc:
            # Wrap any exception in a RuntimeError with context
            raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Normalize args to an iterable of key/value pairs
    items = []

    if isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, dict):
                items.extend(item.items())
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((item[0], item[1]))
            else:
                # Unsupported format; skip
                continue
    else:
        # Unsupported type; return empty dicts
        return control_args, nested_args

    for key, value in items:
        if key is None or not isinstance(key, str):
            continue

        # Determine if this is a control argument
        if key.startswith("control_"):
            stripped = key[len("control_") :]
            control_args[stripped] = value
        # Determine if this is a custom argument
        elif key.startswith("custom_"):
            stripped = key[len("custom_") :]
            nested_args[stripped] = value
        else:
            # Default to nested argument
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple of strings")

    for item in extra_vars:
        if not isinstance(item, str):
            continue
        if '=' not in item:
            continue
        key, value = item.split('=', 1)
        key = key.strip()
        if not key:
            continue
        value = value.strip()

        # Strip surrounding quotes if present
        if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
            value = value[1:-1]

        # Attempt to interpret the value
        try:
            import json
            parsed = json.loads(value)
            value = parsed
        except Exception:
            # Boolean
            if value.lower() == 'true':
                value = True
            elif value.lower() == 'false':
                value = False
            else:
                # Integer
                try:
                    value = int(value)
                except ValueError:
                    # Float
                    try:
                        value = float(value)
                    except ValueError:
                        # List separated by commas
                        if ',' in value:
                            value = [v.strip() for v in value.split(',')]
                        # else keep as string

        vars_dict[key] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Validate playbook path
    if not playbook_path:
        raise ValueError("playbook_path must be provided")
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose:
        try:
            level = int(verbose)
            if level > 0:
                cmd.append("-" + "v" * level)
        except (TypeError, ValueError):
            # If verbose is a string like 'v' or 'vv', just append it
            cmd.append(verbose)

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            import json
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if value is None or value is True:
                cmd.append(key)
            elif value is False:
                # skip
                continue
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([key, str(v)])
            else:
                cmd.extend([key, str(value)])

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # Log output if plugin provides logging
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(f"Command: {' '.join(cmd)}")
        ir_plugin.log(f"Return code: {result.returncode}")
        ir_plugin.log(f"Stdout: {result.stdout}")
        ir_plugin.log(f"Stderr: {result.stderr}")

    # Raise error on non-zero exit
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"Stdout:\n{result.stdout}\n"
            f"Stderr:\n{result.stderr}"
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define type mappings for known parsers. Extend as needed.
    type_map = {
        'main': {
            'count': int,
            'verbose': bool,
            'threshold': float,
            'tags': list,
        },
        'virsh': {
            'timeout': int,
            'debug': bool,
            'options': list,
        },
        'ospd': {
            'port': int,
            'enable': bool,
            'hosts': list,
        },
    }

    # Helper to cast a single value
    def _cast_value(val, target_type):
        if target_type is bool:
            if isinstance(val, str):
                return val.lower() in ('true', '1', 'yes', 'on')
            return bool(val)
        if target_type is list:
            if isinstance(val, str):
                return [v.strip() for v in val.split(',') if v.strip()]
            if isinstance(val, (list, tuple)):
                return list(val)
            return [val]
        try:
            return target_type(val)
        except Exception:
            return val

    # Iterate over the dictionary and cast values
    for key, val in list(values_dict.items()):
        # Skip if value is already a non-string type
        if not isinstance(val, str):
            continue

        # Handle explicit None representation
        if val.strip().lower() in ('none', ''):
            values_dict[key] = None
            continue

        # Determine target type based on parser and key
        target_type = type_map.get(parser_name, {}).get(key)

        if target_type:
            # Cast using the specified type
            casted = _cast_value(val, target_type)
            values_dict[key] = casted
            continue

        # Heuristic casting if no explicit mapping
        lowered = val.strip().lower()
        if lowered in ('true', 'false', '1', '0', 'yes', 'no', 'on', 'off'):
            values_dict[key] = lowered in ('true', '1', 'yes', 'on')
            continue
        # Try integer
        try:
            int_val = int(val)
            values_dict[key] = int_val
            continue
        except ValueError:
            pass
        # Try float
        try:
            float_val = float(val)
            values_dict[key] = float_val
            continue
        except ValueError:
            pass
        # Try comma-separated list
        if ',' in val:
            values_dict[key] = [v.strip() for v in val.split(',') if v.strip()]
            continue
        # Leave as string if no conversion applies

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Determine spec file name
    spec_filenames = ['plugin.yaml', 'plugin.yml', 'plugin.json']
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        # No spec file found
        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception:
        # Unable to read file
        return {}

    # Parse content
    data = None
    if spec_path.endswith(('.yaml', '.yml')):
        try:
            import yaml
            data = yaml.safe_load(content)
        except Exception:
            # YAML parsing failed, try JSON fallback
            try:
                data = json.loads(content)
            except Exception:
                return {}
    else:
        try:
            data = json.loads(content)
        except Exception:
            return {}

    if not isinstance(data, dict):
        return {}

    return _flatten(data)
